def mo_on_tree(n, adj, col, queries):
    """树上莫队（括号序）：路径 u-v 上不同颜色的数量.
    adj: 邻接表 0-indexed; col: 各节点颜色; queries: [(u,v,id)].
    返回按 id 的答案列表."""
    import math, sys
    sys.setrecursionlimit(1 << 20)
    st = [0] * n; ed = [0] * n
    euler = []
    dep = [0] * n
    parent = [-1] * n
    def dfs(u, p):
        parent[u] = p
        st[u] = len(euler); euler.append(u)
        for w in adj[u]:
            if w != p:
                dep[w] = dep[u] + 1
                dfs(w, u)
        ed[u] = len(euler); euler.append(u)
    dfs(0, -1)
    # LCA 用倍增
    LOG = (n + 1).bit_length()
    up = [[-1] * n for _ in range(LOG)]
    up[0] = parent[:]
    for k in range(1, LOG):
        for v in range(n):
            mid = up[k-1][v]
            up[k][v] = up[k-1][mid] if mid != -1 else -1
    def lca(u, v):
        if dep[u] < dep[v]:
            u, v = v, u
        diff = dep[u] - dep[v]
        for k in range(LOG):
            if diff >> k & 1:
                u = up[k][u]
        if u == v:
            return u
        for k in range(LOG - 1, -1, -1):
            if up[k][u] != up[k][v]:
                u = up[k][u]; v = up[k][v]
        return parent[u]
    m2 = len(euler)
    block = max(1, int(math.sqrt(m2)))
    def conv(u, v):
        if st[u] > st[v]:
            u, v = v, u
        w = lca(u, v)
        if w == u:
            return (st[u], st[v], -1)
        return (ed[u], st[v], w)
    converted = []
    for u, v, idx in queries:
        l, r, w = conv(u, v)
        converted.append((l, r, w, idx))
    converted.sort(key=lambda q: (q[0] // block, q[1] if (q[0] // block) % 2 == 0 else -q[1]))
    vis = [0] * n            # 当前在集合中的次数
    cnt = [0] * (max(col) + 1)
    cur = 0
    def toggle(x):
        nonlocal cur
        if vis[x]:
            vis[x] = 0
            cnt[col[x]] -= 1
            if cnt[col[x]] == 0:
                cur -= 1
        else:
            vis[x] = 1
            if cnt[col[x]] == 0:
                cur += 1
            cnt[col[x]] += 1
    ans = [0] * len(queries)
    l = 0; r = -1
    for ql, qr, w, idx in converted:
        while l > ql:
            l -= 1; toggle(euler[l])
        while r < qr:
            r += 1; toggle(euler[r])
        while l < ql:
            toggle(euler[l]); l += 1
        while r > qr:
            toggle(euler[r]); r -= 1
        if w != -1:
            toggle(w)
        ans[idx] = cur
        if w != -1:
            toggle(w)
    return ans

if __name__ == "__main__":
    # 树: 0-1, 0-2, 1-3; 颜色 [1,2,2,3]
    n = 4
    adj = [[1, 2], [0, 3], [0], [1]]
    col = [1, 2, 2, 3]
    queries = [(0, 3, 0), (2, 3, 1), (1, 1, 2)]
    res = mo_on_tree(n, adj, col, queries)
    # 路径 0-3: 0,1,3 -> 颜色 {1,2,3}=3; 2-3: 2,0,1,3 -> {1,2,3}=3; 1-1: {2}=1
    assert res == [3, 3, 1], res
    # 随机交叉验证（小树暴力 BFS 路径）
    import random
    def brute(n, adj, col, u, v):
        # BFS 找路径
        from collections import deque
        par = [-1] * n
        par[u] = u
        q = deque([u])
        while q:
            x = q.popleft()
            if x == v:
                break
            for w in adj[x]:
                if par[w] == -1:
                    par[w] = x
                    q.append(w)
        path = []
        x = v
        while True:
            path.append(x)
            if x == u:
                break
            x = par[x]
        return len(set(col[i] for i in path))
    random.seed(17)
    for _ in range(100):
        n = random.randint(1, 8)
        adj = [[] for _ in range(n)]
        for i in range(1, n):
            p = random.randrange(i)
            adj[i].append(p); adj[p].append(i)
        col = [random.randint(1, 4) for _ in range(n)]
        for _q in range(20):
            u = random.randrange(n); v = random.randrange(n)
            got = mo_on_tree(n, adj, col, [(u, v, 0)])[0]
            exp = brute(n, adj, col, u, v)
            assert got == exp, (n, adj, col, u, v, got, exp)
    print("mo_on_tree OK")
